<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://michiganinsuranceappraiser.com/#business","name":"Michigan Insurance Appraiser","url":"https://michiganinsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@michiganinsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://michiganinsuranceappraiser.com/#logo","url":"https://michiganinsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"Michigan Insurance Appraiser"},"image":{"@id":"https://michiganinsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"MI","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@michiganinsuranceappraiser.com","contactType":"customer service","areaServed":"US-MI","availableLanguage":"en"}],"slogan":"Independent appraisal for underpaid Michigan property claims","description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims in all 83 Michigan counties.","areaServed":[{"@type":"State","name":"Michigan"},{"@type":"City","name":"Detroit"},{"@type":"City","name":"Grand Rapids"},{"@type":"City","name":"Ann Arbor"},{"@type":"City","name":"Lansing"},{"@type":"City","name":"Flint"},{"@type":"City","name":"Dearborn"},{"@type":"City","name":"Troy"},{"@type":"City","name":"Sterling Heights"},{"@type":"City","name":"Kalamazoo"},{"@type":"City","name":"Saginaw"},{"@type":"City","name":"Traverse City"},{"@type":"City","name":"Marquette"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Demand Representation","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/appraisal-demand-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowner Claim Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/homeowner-claim-appraiser/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial, Condo & HOA Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/commercial-condo-hoa-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Hail & Roof Damage Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/hail-roof-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Windstorm & Tornado Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/windstorm-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam & Frozen Pipe Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/ice-dam-frozen-pipe-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water & Sewer Backup Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/water-sewer-backup-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Loss Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/fire-smoke-loss-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fallen Tree & Ice Storm Appraisal","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/fallen-tree-ice-storm-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Contents & Personal Property","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/contents-personal-property-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Estimate Second Opinion","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/insurance-estimate-second-opinion/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Neutral Umpire Services","url":"https://michiganinsuranceappraiser.com/michigan-claim-appraisal/neutral-umpire-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Xactimate estimating","Ice dam claims","Sewer backup claims","Hail damage"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://michiganinsuranceappraiser.com/#website","url":"https://michiganinsuranceappraiser.com/","name":"Michigan Insurance Appraiser","publisher":{"@id":"https://michiganinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-questions/#webpage","url":"https://michiganinsuranceappraiser.com/michigan-appraisal-questions/","name":"Michigan Insurance Appraisal FAQ | Costs & Timing","description":"Michigan insurance appraisal FAQ, grouped by topic: how appraisal works, what it costs, deadlines, state rules and how we work with owners.","inLanguage":"en-US","isPartOf":{"@id":"https://michiganinsuranceappraiser.com/#website"},"about":{"@id":"https://michiganinsuranceappraiser.com/#business"},"publisher":{"@id":"https://michiganinsuranceappraiser.com/#business"},"dateModified":"2026-11-18","primaryImageOfPage":{"@type":"ImageObject","url":"https://michiganinsuranceappraiser.com/assets/img/photos/living-room.webp","width":1200,"height":797},"breadcrumb":{"@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-questions/#breadcrumb"},"mainEntity":{"@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-questions/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://michiganinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal FAQ","item":"https://michiganinsuranceappraiser.com/michigan-appraisal-questions/"}],"@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-questions/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"Insurance appraisal is a process written into your property policy for settling disagreements about the amount of a loss. Each side picks an appraiser, the appraisers choose an umpire, and a written award signed by two of the three sets the figure. It is usually faster and less expensive than going to court."}},{"@type":"Question","name":"Does appraisal decide whether my claim is covered?","acceptedAnswer":{"@type":"Answer","text":"No. Appraisal decides how much the loss is worth, not whether the policy covers it. If your insurer has denied coverage, a Michigan attorney is the right person to talk to about that question."}},{"@type":"Question","name":"Is appraisal binding in Michigan?","acceptedAnswer":{"@type":"Answer","text":"A written award signed by any two of the three participants determines the amount of loss under the appraisal framework in Michigan’s Insurance Code. Awards can be challenged in limited situations, such as fraud or a serious problem with the process. Check your policy wording and ask an attorney if you’re concerned about a specific award."}},{"@type":"Question","name":"Can my insurer demand appraisal too?","acceptedAnswer":{"@type":"Answer","text":"Yes. Under the general framework in MCL 500.2833, either the insured or the insurer can make a written demand for appraisal when they disagree on the actual cash value or amount of loss. Some insurers invoke it to bring a long negotiation to a close."}},{"@type":"Question","name":"What kinds of claims go to appraisal?","acceptedAnswer":{"@type":"Answer","text":"Any covered property loss with a disputed dollar amount can be a candidate, including hail, wind, tornado, fire, smoke, ice dam, frozen pipe, fallen tree and sewer backup claims. Both homeowner and commercial policies in Michigan contain appraisal provisions. The key is that the dispute is about price, quantity or scope rather than coverage."}},{"@type":"Question","name":"Who pays for appraisal?","acceptedAnswer":{"@type":"Answer","text":"Most policies say each side pays its own appraiser and the two sides split the umpire’s fee equally. Your policy wording controls, so read the appraisal clause for its cost terms. Appraisal awards generally don’t shift attorney fees or appraisal costs to the insurer."}},{"@type":"Question","name":"How do appraisers charge?","acceptedAnswer":{"@type":"Answer","text":"Appraisers commonly use a flat fee, an hourly rate or a percentage of the award, and some combine them. Whatever the arrangement, it should be in writing before any work begins. Ask how expenses such as travel, engineering or roof measurement reports are handled."}},{"@type":"Question","name":"Is appraisal worth it on a small claim?","acceptedAnswer":{"@type":"Answer","text":"It depends on the size of the gap compared with the cost of the process. If the difference between estimates is only a few thousand dollars, the appraisal and umpire fees may consume much of what you would recover. Our claim gap and fee estimator can help you compare the numbers."}},{"@type":"Question","name":"What does an umpire cost?","acceptedAnswer":{"@type":"Answer","text":"Umpires usually charge an hourly rate or a set fee, and the cost rises with the number of items they must decide. Most policies split the umpire’s fee between the two sides. Settling as many items as possible between the appraisers keeps umpire costs down."}},{"@type":"Question","name":"How long does appraisal take in Michigan?","acceptedAnswer":{"@type":"Answer","text":"Many appraisals wrap up within a few months, but timing varies with the size of the loss, scheduling and how many items reach the umpire. Michigan’s statute generally gives each side 20 days to name an appraiser and the appraisers 15 days to pick an umpire. Winter weather in northern Michigan and the U.P. can delay roof inspections."}},{"@type":"Question","name":"Is there a deadline to file suit on a property claim?","acceptedAnswer":{"@type":"Answer","text":"Michigan’s Insurance Code generally requires suit within one year after the loss, or a longer period if the policy allows, with that period tolled from when you give notice until the insurer formally denies liability. How this applies to your claim depends on the facts. Talk with a Michigan attorney about your specific deadlines."}},{"@type":"Question","name":"Does demanding appraisal stop the suit deadline?","acceptedAnswer":{"@type":"Answer","text":"Not necessarily. Appraisal and the suit limitation are separate issues, and you shouldn’t assume one pauses the other. If the deadline is approaching, get advice from a Michigan attorney right away."}},{"@type":"Question","name":"When should I demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Usually after you’ve given the insurer your documents, received its estimate and tried in good faith to resolve the difference. If negotiation has stalled and the gap is about money rather than coverage, appraisal is worth considering. Don’t wait so long that suit deadlines become a problem."}},{"@type":"Question","name":"How soon will I get paid after the award?","acceptedAnswer":{"@type":"Answer","text":"Policies often set a payment period after the amount of loss is agreed or determined by appraisal, commonly measured in days. Check your policy’s loss payment condition for the exact window. Recoverable depreciation is often released later, once repairs are completed."}},{"@type":"Question","name":"What law governs appraisal in Michigan?","acceptedAnswer":{"@type":"Answer","text":"MCL 500.2833 in Michigan’s Insurance Code requires fire and property policies to contain an appraisal provision and sets its general framework. Your policy restates the provision in its own words, and the policy language governs the details. Always read your own policy rather than relying on a summary."}},{"@type":"Question","name":"Who regulates insurers in Michigan?","acceptedAnswer":{"@type":"Answer","text":"The Michigan Department of Insurance and Financial Services, known as DIFS, regulates insurers doing business in the state. Policyholders can file a complaint with DIFS if they believe an insurer has handled a claim improperly. A complaint doesn’t replace appraisal or legal advice, but it creates a record."}},{"@type":"Question","name":"What is the MBPIA?","acceptedAnswer":{"@type":"Answer","text":"The Michigan Basic Property Insurance Association is Michigan’s FAIR Plan, offering basic property coverage to owners who can’t get it in the voluntary market. MBPIA policies also contain appraisal provisions. Coverage is often more limited than a standard homeowner policy, so read the forms carefully."}},{"@type":"Question","name":"Does Michigan have penalty interest on late claims?","acceptedAnswer":{"@type":"Answer","text":"MCL 500.2006 provides for penalty interest of 12% per year on certain claims that aren’t paid on time. Whether it applies depends on the facts and how the statute is read, so it isn’t automatic. Appraisers don’t award it; ask a Michigan attorney if you think payment is late."}},{"@type":"Question","name":"Are ice dam and basement backup claims common in Michigan?","acceptedAnswer":{"@type":"Answer","text":"Yes. Lake-effect snow belts, cold snaps like the January 2019 polar vortex and older roofs make ice dams a routine winter claim. Nearly universal basements in the Lower Peninsula mean sewer and drain backups after heavy rain, like the 2014 and 2021 metro Detroit floods, are also frequent."}},{"@type":"Question","name":"Do you offer a free review?","acceptedAnswer":{"@type":"Answer","text":"Yes. We offer a free initial review of your policy, the insurer’s estimate and your documents. We’ll tell you plainly whether appraisal looks like a good fit or whether another path makes more sense."}},{"@type":"Question","name":"How do your fees work?","acceptedAnswer":{"@type":"Answer","text":"We discuss flat, hourly and percentage arrangements up front and put the fee terms in writing before any work begins. The right structure depends on the size and complexity of the claim. There are no surprise charges added later."}},{"@type":"Question","name":"Where in Michigan do you work?","acceptedAnswer":{"@type":"Answer","text":"We work statewide, across both peninsulas and all 83 counties, including the U.P. Some inspections are scheduled around weather and travel, especially in winter up north."}},{"@type":"Question","name":"Can you be both my appraiser and the umpire?","acceptedAnswer":{"@type":"Answer","text":"No. We take one role per claim, either as your appraiser, as an estimate reviewer or as a neutral umpire. Keeping roles separate protects the independence of the process and the award."}},{"@type":"Question","name":"Are you lawyers or public adjusters?","acceptedAnswer":{"@type":"Answer","text":"No. We are independent appraisers and estimate reviewers, not a law firm, and we don’t give legal advice or act as public adjusters. If your claim involves a coverage denial or legal deadline, we’ll suggest you speak with a Michigan attorney."}}],"@id":"https://michiganinsuranceappraiser.com/michigan-appraisal-questions/#faq"}]}</script>
</head>
